#include <bits/stdc++.h>
using namespace std;

static const int MAXV = 1000000;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n;
        cin >> n;

        vector<int> a(n), b(n);
        for (int &x : a) cin >> x;
        for (int &x : b) cin >> x;

        sort(a.begin(), a.end());
        sort(b.begin(), b.end());

        if (a == b) {
            cout << 1000000000 << '\n';
            continue;
        }

        int maxA = a.back();
        int maxB = b.back();

        vector<int> cntA(MAXV + 1, 0), cntB(MAXV + 1, 0);
        for (int x : a) ++cntA[x];
        for (int x : b) ++cntB[x];

        int firstBad = MAXV + 1;
        for (int x = 0; x <= MAXV; ++x) {
            if (cntA[x] > cntB[x]) {
                firstBad = x;
                break;
            }
        }

        vector<int> candidates;
        vector<int> uniqueB = b;
        uniqueB.erase(unique(uniqueB.begin(), uniqueB.end()), uniqueB.end());

        for (int x : uniqueB) {
            int d = maxA - x;
            if (d <= 0) continue;

            for (int p = 1; 1LL * p * p <= d; ++p) {
                if (d % p != 0) continue;

                int q = d / p;
                if (p > maxB) candidates.push_back(p);
                if (q != p && q > maxB) candidates.push_back(q);
            }
        }

        sort(candidates.begin(), candidates.end(), greater<int>());
        candidates.erase(unique(candidates.begin(), candidates.end()), candidates.end());

        vector<int> seen(MAXV + 1, 0), stamp(MAXV + 1, 0);
        int currentStamp = 0;
        int answer = -1;

        for (int k : candidates) {
            if (k <= maxB || k > 1000000000) continue;
            if (firstBad < k) continue;

            ++currentStamp;
            bool ok = true;
            int start = lower_bound(a.begin(), a.end(), k) - a.begin();

            for (int i = start; i < n; ++i) {
                int r = a[i] % k;
                int required = cntB[r] - cntA[r];

                if (stamp[r] != currentStamp) {
                    stamp[r] = currentStamp;
                    seen[r] = 0;
                }

                if (++seen[r] > required) {
                    ok = false;
                    break;
                }
            }

            if (ok) {
                answer = k;
                break;
            }
        }

        cout << answer << '\n';
    }

    return 0;
}
```

Stage 1 - Final failure: Step 2 produces the same flawed algorithm and outputs `-1` for the fourth sample, while the correct answer is `4`. For that case, independently sorting `a` and `b` gives gcd `1`, even though `a mod 4` is exactly the multiset `b`.

Stage 2 - Flag erroneous steps:
- Step 0, architect, `(R.4, PL.1)`: the claim that sorted elements must correspond and that `k` divides every sorted difference is false because `b` was shuffled; sorting destroys the valid matching.
- Step 1, engineer, `(R.4)`: the code implements the architect's invalid sorted-pairing reduction, so it fails the fourth sample and other cases where the residue matching is not order-preserving.
- Step 2, reviewer, `(V.2)`: “No issues found” is an incorrect verification; checking the supplied fourth sample would immediately reveal that the code prints `-1` instead of `4`.

Stage 3 - Originating or propagated: Step 0 is ORIGINATING because it introduces the invalid correspondence assumption. Steps 1 and 2 are PROPAGATED from Step 0, with Step 2 additionally failing to verify the implementation against the sample.

Stage 4 - Earliest decisive step: Step 0 is the earliest decisive error; correcting the assumption about sorted correspondence requires replacing the core candidate-generation and validation strategy.

