        int n, k;
        cin >> n >> k;

        vector<long long> d(n);
        for (auto &x : d) cin >> x;

        priority_queue<long long, vector<long long>, greater<long long>> pq;
        long long answer = 0;

        for (int i = n - 1; i >= 0; --i) {
            int capacity = (n - i) / (k + 1);

            if ((int)pq.size() < capacity) {
                pq.push(d[i]);
                answer += d[i];
            } else if (capacity > 0 && d[i] > pq.top()) {
                answer -= pq.top();
                pq.pop();
                pq.push(d[i]);
                answer += d[i];
            }
        }

        cout << answer << '\n';
    }

    return 0;
}
